import { DEPOSIT_POOLS } from "./constants"

export const STAKING_ACTIONS_DISABLED = true
export const HEYAURA_STAKING_URL = "http://app.heyaura.com/staking"
export const MIGRATION_ANNOUNCEMENT_URL =
	"https://blog.heyaura.com/adx-staking-migration/"

// The loyalty pool does not migrate to the new staking, so its
// deposit/withdraw actions stay available here.
export const STAKING_MIGRATION_EXEMPT_POOL_IDS = [DEPOSIT_POOLS[0].id]

export const isStakingMigrationExempt = poolId =>
	STAKING_MIGRATION_EXEMPT_POOL_IDS.includes(poolId)

export const blockStakingAction = (onBlocked, poolId) => {
	if (!STAKING_ACTIONS_DISABLED) return false
	if (isStakingMigrationExempt(poolId)) return false

	if (typeof onBlocked === "function") onBlocked()
	return true
}

export const withStakingMigrationGuard = (onBlocked, action, poolId) => async (
	...args
) => {
	if (blockStakingAction(onBlocked, poolId)) return undefined
	return action(...args)
}
